'use strict';
let creatorMode='create',pendingSlot=-1,previewJob='warrior';
function drawCharacterPreview(){}
function classRatings(data){const wrap=document.createElement('div');wrap.className='class-ratings';['AOE · โจมตีหมู่','Easy · เล่นง่าย','Endurance · ความทนทาน'].forEach((label,index)=>{const row=document.createElement('div'),text=document.createElement('small');text.textContent=label;row.append(text);const cells=document.createElement('span');for(let i=0;i<5;i++){const cell=document.createElement('i');cell.classList.toggle('filled',i<data.ratings[index]);cells.append(cell)}row.append(cells);wrap.append(row)});return wrap}
function showCreator(mode){creatorMode=mode;previewJob='warrior';$('creatorTitle').textContent='สร้างตัวละคร · เลือกอาชีพหลัก';$('characterName').value='Fern';$('createCharacterBtn').hidden=false;$('promoteBtn').hidden=true;$('creatorEyebrow').textContent='อาวุธกำหนดชุดสกิล · ไม่มีการเลื่อนขั้นอาชีพ';document.querySelector('.advancement-requirements').hidden=true;document.querySelector('.creator-layout').hidden=true;let cards=$('baseClassCards');if(!cards){cards=document.createElement('div');cards.id='baseClassCards';document.querySelector('.creator-footer').parentElement.insertBefore(cards,document.querySelector('.creator-footer'))}cards.replaceChildren();for(const [id,data]of Object.entries(BASE_CLASSES)){const card=document.createElement('button');card.type='button';card.className='base-class-card';card.dataset.class=id;card.setAttribute('aria-pressed',String(id===previewJob));const title=document.createElement('h3');title.textContent=data.name;const icon=document.createElement('div');icon.className='class-card-icon';icon.textContent={warrior:'⚔',shooter:'➶',mage:'✦',rogue:'✧'}[id];const weapons=document.createElement('p');weapons.textContent='อาวุธ: '+data.weapons.map(w=>WEAPON_NAMES[w]).join(' / ');const stat=document.createElement('strong');stat.textContent='สเตตัสหลัก '+STAT_NAMES[data.main];card.append(title,icon,weapons,stat,classRatings(data));card.onclick=()=>{previewJob=id;cards.querySelectorAll('button').forEach(b=>{b.classList.toggle('selected',b===card);b.setAttribute('aria-pressed',String(b===card))});$('creatorSummary').textContent=data.name+' · '+STAT_NAMES[data.main]};card.classList.toggle('selected',id===previewJob);cards.append(card)}$('creatorSummary').textContent='เลือกอาชีพเพื่อกำหนดอาวุธที่ถือได้';switchScreen('creator')}
function openCreator(index){if(!Number.isInteger(index)||index<0||index>=3||slots[index])return;activeSlot=-1;pendingSlot=index;showCreator('create')}
function leaveCreator(){pendingSlot=-1;switchScreen('saves')}
function createCharacter(event){event.preventDefault();if(screen!=='creator'||pendingSlot<0||slots[pendingSlot])return;const name=$('characterName').value.trim().normalize('NFC');if(!name||name.length>24){$('characterName').setCustomValidity('ตั้งชื่อ 1–24 ตัวอักษร');$('characterName').reportValidity();return}const index=pendingSlot;slots[index]={character:{...fresh(),name,baseClass:previewJob,job:previewJob},savedAt:new Date().toISOString()};pendingSlot=-1;persist();loadSlot(index)}
function openCareer(){openControlWindow('skill')}
function renderTrialEntry(){const box=$('trialEntry');box.replaceChildren();const label=document.createElement('p');label.textContent=player.classTier>=2?'เลื่อนครบขั้น 2 แล้ว':player.advancementMark?'มีตราแล้ว · กดใช้ในหมวดใช้งาน':'สู้บอสเพื่อรับตราเลื่อนขั้น '+(player.classTier+1)+' · Lv.'+SKILL_MIN_LEVEL[player.classTier+1];const start=document.createElement('button');start.id='trialStartBtn';start.textContent='ท้าทายบอส';start.disabled=!canEnterTrial();start.onclick=()=>beginStage(4);box.append(label,start)}
function renderStages(){renderStoryStages();renderTrialEntry();selectStageCategory(stageCategory)}
$('creatorBack').onclick=leaveCreator;$('characterForm').onsubmit=createCharacter;$('characterName').oninput=()=>$('characterName').setCustomValidity('');$('careerBtn').onclick=openCareer;

